// n'a besoin de répondre juste : une fonction vide pour tout suffit.
function contexteFactice() {
  const rien = () => {};
  return new Proxy(
    {},
    {
      get: (_, nom) => (nom === 'canvas' ? { width: WIDTH, height: HEIGHT } : rien),
      set: () => true,
    },
  );
}

