```js
// Handles brick collisions for one step: discrete overlaps first (the ball is
// inside the brick at the new position), then the swept path between the
// previous and the new position (a fast ball can cross a brick without ever
// overlapping at a sample point). Breaks every overlapping brick, applies ONE
// bounce per pass (two bounces on the same frame would cancel out and let the
// ball through — see the seam cases) and returns true when something bounced.
function bounceOffBricks(state, prevX, prevY) {
  const { ball } = state;

  // Discrete overlaps: the ball ends the step inside one or more bricks.
  let target = null;
  let minPenetration = Infinity;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (!collides(ball, brick)) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    const penetration = Math.min(
      ball.x + ball.r - brick.x,
      brick.x + brick.w - (ball.x - ball.r),
      ball.y + ball.r - brick.y,
      brick.y + brick.h - (ball.y - ball.r),
    );
    if (penetration < minPenetration) {
      minPenetration = penetration;
      target = brick;
    }
  }
  if (target) {
    resolveBrickOverlap(ball, target);
    return true;
  }

  // Swept path: the ball crossed a brick between its previous and new
  // position without ending inside it (tunneling at high speed).
  let best = null;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweptBrickHit(ball, brick, prevX, prevY);
    if (!hit) continue;
    if (!best || hit.t < best.hit.t) best = { brick, hit };
  }
  if (best) {
    const { brick, hit } = best;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    ball.x = prevX + (ball.x - prevX) * hit.t;
    ball.y = prevY + (ball.y - prevY) * hit.t;
    bounceOffFace(ball, hit.face);
    return true;
  }
  return false;
}
```

